const number = value => value == null ? '—' : new Intl.NumberFormat('en-US', { maximumFractionDigits: 6 }).format(value);
const signed = value => value == null ? '—' : `${value > 0 ? '+' : value < 0 ? '−' : ''}${value!==0&&Math.abs(value)<0.000001?'&lt;0.000001':number(Math.abs(value))}`;
